import{_ as e,o as a,c as l,Q as r}from"./chunks/framework.48927342.js";const f=JSON.parse('{"title":"马耳他语入门目录","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/grammar/index.md","filePath":"zh/more/maltese/grammar/index.md"}'),o={name:"zh/more/maltese/grammar/index.md"},t=r('<h1 id="马耳他语入门目录" tabindex="-1">马耳他语入门目录 <a class="header-anchor" href="#马耳他语入门目录" aria-label="Permalink to &quot;马耳他语入门目录&quot;">​</a></h1><p>这套笔记面向零基础学习者，马耳他语采用标准拉丁字母拼写。表格中的中文和英文释义用于快速记忆；实际语境中词义可能随搭配变化。</p><h2 id="学习资料" tabindex="-1">学习资料 <a class="header-anchor" href="#学习资料" aria-label="Permalink to &quot;学习资料&quot;">​</a></h2><p></p><ul><li><a href="./00-requirements.html">00 编写要求</a>：记录本套马耳他语入门资料的原始内容范围与编写要求。</li></ul><ol><li><a href="./01-vocabulary.html">分类基础词汇</a>：十个主要类别各至少 20 条；亲属、房屋、动物、植物、交通和时间词的单复数及适用的语法性别直接列在对应表格中，动物表另注明公母专称；时间按时、天、周、月、年整理，疑问词和介词按常用程度排序。</li><li><a href="./02-phrases.html">200 个常用短语</a>：分为 10 个场景，每类 20 条，覆盖问候、礼貌用语、交谈、餐饮、购物、出行、时间、日常需要和紧急情况。</li><li><a href="./03-person-conjugation.html">动词人称变位与人称代词</a>：先讲变位规则，再以独立列展示 5 个常用动词及词首/词中含 <code>għ</code> 的各 5 个动词的中英马词义和七个人称形式；另附每个动词的三语例句，不讲时态。</li><li><a href="./04-verbs-tenses.html">动词与基本时态</a>：先讲未完成式、完成式和将来表达，再在各时态说明中分别列出 10 个常用动词及词首/词中含 <code>għ</code> 的各 5 个动词的中英马词义与七个人称变位（每个人称独立一列），并为第一人称单数配三语例句。</li><li><a href="./05-numbers.html">数字与数词语法</a>：三语基数词、复合数字、20 个序数词及 10 个大数示例。</li><li><a href="./06-time-calendar.html">时间表达</a>：依次讲整点、早/午/晚与相对日期、时分读法、时间长度；包含 <code>u</code>/<code>nofs</code>/<code>neqsin</code> 用法，以及各 20 个时刻和时长短语。</li><li><a href="./07-dates.html">日期、星期、月份与季节</a>：日期读法、日历词汇、上/本/下周月年表达及 20 个中英马例句。</li><li><a href="./08-prepositions.html">常用介词</a>：按常用程度列出 44 个常用介词和固定搭配，逐项对照 <code>il-</code>、<code>l-</code>、<code>is-</code>、<code>id-</code>、<code>it-</code> 五类冠词形式，说明缩合限制，并为各项提供中英马例句。</li></ol><h2 id="推荐学习顺序" tabindex="-1">推荐学习顺序 <a class="header-anchor" href="#推荐学习顺序" aria-label="Permalink to &quot;推荐学习顺序&quot;">​</a></h2><p>先熟悉字母和分类词汇，再按场景练习 200 个常用短语；随后按人称变位、时态、数字、时间、日期和介词的顺序学习。每天选 5 到 10 个词，用本套例句替换词语造句，并大声朗读。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><p></p><ul><li>马耳他语中的 <code>ċ</code>、<code>ġ</code>、<code>ħ</code>、<code>ż</code> 是独立字母；<code>għ</code> 和 <code>ie</code> 也要按原样记忆，不要省略变音符号。</li><li>马耳他语有地区和口语差异。这里优先列出标准书写中常见的形式；个别表达可能有其他自然说法。</li><li>马耳他语动词没有与英语完全对应的不定式形式。词汇表中的动词以常见的现在式形式展示，具体人称形式请看变位表。</li></ul><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p></p><ul><li><a href="https://en.wikipedia.org/wiki/Maltese_language" target="_blank" rel="noreferrer">Maltese language（含语法概览）</a></li><li><a href="https://kunsilltalmalti.gov.mt/" target="_blank" rel="noreferrer">马耳他语国家委员会</a></li><li><a href="https://www.um.edu.mt/library/oar/handle/123456789/351" target="_blank" rel="noreferrer">马耳他大学图书馆：Maltese languages and literatures</a>   本套内容为学习笔记，适合作为入门速查；遇到正式写作或重要翻译，应再查马耳他语词典或请母语者校订。</li></ul>',14),i=[t];function d(c,n,h,s,m,u){return a(),l("div",null,i)}const p=e(o,[["render",d]]);export{f as __pageData,p as default};
